// 继位来源链只连接原意愿、死亡与本人实收文书；全局可见的死亡记录不是本人知识。
#include "political_succession_accession_sources.hpp"
#include "political_succession_nomination_detail.hpp"
#include "resident/domains/tasks/message_notices/task_message_notice_history.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
#include <limits>
namespace hanmo::resident {namespace {
// 事实必须同时具备原kind/domain、规范全局实例号和真实Common位置。
std::optional<Integer> fact(const CommonStore& c,const StableId& id,const StableId& prefix,const StableId& kind,const StableId& domain){const auto* h=c.state().facts.find(id);const auto n=organization_instance_sequence(id,prefix);if(!h||h->id!=id||h->kind!=kind||h->domain!=domain||!n||*n>=c.state().next_instance_id)return {};return n;}
// 所有被引用原事实均须真的在就任截面前；单独改ID或重排Common都不能取得许可。
bool precedes(const CommonStore& c,const StableId& a,const StableId& b){const auto& order=c.state().facts.order();auto x=std::find(order.begin(),order.end(),a),y=std::find(order.begin(),order.end(),b);auto number=[&](const StableId& id){auto colon=id.find(':');return colon==StableId::npos?std::optional<Integer>{}:organization_instance_sequence(id,id.substr(0,colon));};auto n=number(a),m=number(b);return n&&m&&*n<*m&&*m<c.state().next_instance_id&&x!=order.end()&&y!=order.end()&&x<y;}
// 首片不覆盖仍在代办的副手，也不以两个以上已发生的换任循环复活旧死者授权。
Outcome<PoliticalSuccessionAccessionBasis> read(const PoliticalSuccessionAccessionSourceContext& ctx,const StableId& acceptance_id,const StableId& death_id,const StableId& binding_id,Integer tick,const StableId& boundary){
 const auto& x=ctx.nominations;const auto& common=x.common;auto fail=[&](const StableId& code){return Outcome<PoliticalSuccessionAccessionBasis>{false,{},common_failure(code,acceptance_id).error};};
 if(tick<0||tick>common.tick()||(boundary.empty()&&tick!=common.tick()))return fail("PoliticalSuccessionAccessClockMismatch");
 if(!boundary.empty()&&!fact(common,boundary,"political_succession_accession","political_succession_acceded",political_succession_domain))return fail("PoliticalSuccessionAccessBoundaryRequired");
 const auto* accepted=x.state.answers.find(acceptance_id);const auto* n=accepted?x.state.nominations.find(accepted->nomination_fact_id):nullptr;const auto* policy=n?x.catalog.policies.find(n->policy_id):nullptr;
 if(!accepted||accepted->id!=acceptance_id||!accepted->accepted||!accepted->previous_acceptance_fact_id.empty()||!n||!policy||accepted->actor_id!=n->candidate_actor_id||accepted->tick<n->issued_tick||accepted->tick>=n->response_until||accepted->tick>tick||!fact(common,n->id,"political_succession_nomination","political_successor_nominated",political_succession_domain)||!fact(common,accepted->id,"political_succession_acceptance","political_succession_accepted",political_succession_domain)||!precedes(common,n->id,accepted->id)||(!boundary.empty()&&!precedes(common,accepted->id,boundary)))return fail("PoliticalSuccessionAcceptedSourceRequired");
 // 历史只拒该截面前的真实关闭；此后的记录由完整政治业务史核验，不能倒改旧就任。
 for(const auto& row:x.state.answers.rows())if(row.second.nomination_fact_id==n->id&&!row.second.accepted&&(boundary.empty()||precedes(common,row.first,boundary)))return fail("PoliticalSuccessionWillingnessClosed");
 for(const auto& row:x.state.withdrawals.rows())if(row.second.nomination_fact_id==n->id&&(boundary.empty()||precedes(common,row.first,boundary)))return fail("PoliticalSuccessionWillingnessClosed");
 auto death=boundary.empty()?read_actor_death(common,ctx.deaths,n->issuer_actor_id):read_actor_death_before_fact(common,ctx.deaths,n->issuer_actor_id,tick,boundary);
 if(!death.ok)return {false,{},death.error};if(!death.value||death.value->death_fact_id!=death_id)return fail("PoliticalSuccessionActualDeathRequired");const auto& d=*death.value;
 if(!fact(common,death_id,"family_death","family_death","family_life")||!fact(common,d.cause_fact_id,"military","military_casualties","military")||!precedes(common,accepted->id,d.cause_fact_id)||!precedes(common,d.cause_fact_id,death_id)||accepted->tick>d.death_tick||d.death_tick>std::numeric_limits<Integer>::max()-policy->accession_ticks||tick>=d.death_tick+policy->accession_ticks)return fail("PoliticalSuccessionDeathOrDeadlineMismatch");
 if(!ctx.delivered_notice)return fail("PoliticalSuccessionNoticeReadRequired");auto notice=boundary.empty()?ctx.delivered_notice(n->candidate_actor_id,binding_id):read_task_death_notice_before_political_accession(common,ctx.delivered_notice,n->candidate_actor_id,binding_id,tick,boundary);if(!notice.ok)return {false,{},notice.error};if(!notice.value)return fail("PoliticalSuccessionDeathNotKnown");const auto& received=*notice.value;const auto& a=received.identity;const auto& b=common.state().identity;
 if(std::tie(a.world_id,a.execution_epoch,a.revision,a.tick)!=std::tie(b.world_id,b.execution_epoch,b.revision,b.tick)||received.binding_fact_id!=binding_id||received.recipient_actor_id!=n->candidate_actor_id||received.decedent_actor_id!=n->issuer_actor_id||received.death_fact_id!=death_id||received.received_tick<received.issued_tick||received.issued_tick<d.recorded_tick||received.received_tick>tick||!fact(common,binding_id,"task_death_notice_bound","task_death_notice_bound","tasks")||!fact(common,received.handoff_fact_id,"task_message_handoff","task_message_handoff","tasks")||!precedes(common,death_id,binding_id)||!precedes(common,binding_id,received.handoff_fact_id)||(!boundary.empty()&&!precedes(common,received.handoff_fact_id,boundary)))return fail("PoliticalSuccessionNoticeSourceMismatch");
 auto office=boundary.empty()?read_political_succession_office(common,x.organizations,x.organization_catalog,*policy):read_political_succession_office_before(common,x.organizations,x.organization_catalog,*policy,tick,boundary);if(!office.ok)return {false,{},office.error};const auto& o=office.value;
 if(!o.vacant)return fail("PoliticalSuccessionOfficeNotVacant");if(n->office_epoch==std::numeric_limits<Integer>::max()||o.office_epoch!=n->office_epoch+1)return fail("PoliticalSuccessionDeputyHandoverRequired");const auto* vacancy=x.organizations.facts.find(o.latest_office_fact_id);
 if(!vacancy||!vacancy->actor_id.empty()||vacancy->office_id!=n->office_id||vacancy->organization_id!=n->organization_id||vacancy->tick<d.death_tick||vacancy->tick>tick||!fact(common,vacancy->id,"organization","organization_office_changed","organization")||!precedes(common,d.cause_fact_id,vacancy->id)||(!boundary.empty()&&!precedes(common,vacancy->id,boundary)))return fail("PoliticalSuccessionVacancySourceMismatch");
 return {true,{common.state().identity,n->id,accepted->id,policy->id,n->organization_id,n->office_id,n->issuer_actor_id,n->candidate_actor_id,death_id,d.cause_fact_id,binding_id,received.handoff_fact_id,vacancy->id,boundary,d.death_tick,received.received_tick,o.office_epoch,tick},{}};
}
}
Outcome<PoliticalSuccessionAccessionBasis> read_political_succession_accession_basis(const PoliticalSuccessionAccessionSourceContext& x,const StableId& a,const StableId& d,const StableId& n){return read(x,a,d,n,x.nominations.common.tick(),{});}
Outcome<PoliticalSuccessionAccessionBasis> read_political_succession_accession_basis_before(const PoliticalSuccessionAccessionSourceContext& x,const StableId& a,const StableId& d,const StableId& n,Integer tick,const StableId& fact_id){if(fact_id.empty())return {false,{},common_failure("PoliticalSuccessionAccessBoundaryRequired").error};return read(x,a,d,n,tick,fact_id);}
}
